package io.github.rezabakhshi.embedra.analyzers.crypto.hardware;

import io.github.rezabakhshi.embedra.analyzers.crypto.CryptoFinding;
import java.util.Collections;
import java.util.List;
import java.util.Objects;

/**
 * Report generated by hardware crypto analysis (AN-010, AN-013).
 *
 * @param findings list of discovered cryptographic findings
 * @param totalDetections count of detected hardware/ROM/crypto events
 */
public record HardwareCryptoReport(
        List<CryptoFinding> findings,
        int totalDetections) {

    public HardwareCryptoReport {
        findings = findings == null ? List.of() : Collections.unmodifiableList(List.copyOf(findings));
        if (totalDetections < 0) {
            throw new IllegalArgumentException("totalDetections must be non-negative: " + totalDetections);
        }
    }
}
